entries[203366] = { ["name"] = "Blue Winglord's Staff", ["text"] = "Binds when picked up\nTwo-Hand Staff\n7 - 10 Damage Speed 3.60\n(2.4 damage per second)\n+28 Intellect\n+9 Stamina\n+ 5 Critical Strike\n+ 7 Haste\nDurability 85 / 85\nClasses: Evoker\nSell Price:" }
