entries[203375] = { ["name"] = "Crimson Combatant's Medallion", ["text"] = "Binds when equipped\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+205 [Agility or Strength or Intellect]\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[203376] = { ["name"] = "Crimson Combatant's Insignia of Alacrity", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 291 Haste\nEquip: Your spells and abilities have a chance to grant 457 primary stat for 20 sec.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[203377] = { ["name"] = "Crimson Combatant's Emblem", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+205 [Agility or Strength or Intellect]\nUse: Increases maximum health by 26226 for 15 sec. (2 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[203378] = { ["name"] = "Technique: Crimson Combatant's Medallion", ["text"] = "Use: Teaches you how to craft Crimson Combatant's Medallion.\nRequires Dragon Isles Inscription (35)\nSell Price:" }
entries[203379] = { ["name"] = "Technique: Crimson Combatant's Insignia of Alacrity", ["text"] = "Use: Teaches you how to craft Crimson Combatant's Insignia of Alacrity.\nRequires Dragon Isles Inscription (35)\nSell Price:" }
entries[203380] = { ["name"] = "Technique: Crimson Combatant's Emblem", ["text"] = "Use: Teaches you how to craft Crimson Combatant's Emblem.\nRequires Dragon Isles Inscription (35)\nSell Price:" }
entries[203381] = { ["name"] = "Sealed Letter to Neltharion", ["text"] = "Quest Item\n\"A perfumed scent emanates from the letter... centuries old... yet oddly familiar.\"" }
entries[203382] = { ["name"] = "Peripheral Vision Projectors", ["text"] = "Binds when picked up\nHead Leather\n282 Armor\n+257 [Agility or Intellect]\n+416 Stamina\n+ 478 Mastery\n\nTinker Socket\nRequires Dragon Isles Engineering (1)\nSell Price:" }
entries[203383] = { ["name"] = "Notes on Dragonkin Equality", ["text"] = "Quest Item\nUse: Let dragonkin know that equality is imminent.\n\"Shows the dragonkin that Alexstrasza is planning to make changes.\"" }
entries[203385] = { ["name"] = "Flamesight Rune", ["text"] = "Quest Item\n\"The totem dims as you remove this rune. They seem to be attuned to each other.\"" }
entries[203386] = { ["name"] = "Box of Leapmaize Crackers", ["text"] = "Quest Item\nUnique\n\"A box of crackers branded with The Roasted Ram.\"" }
entries[203387] = { ["name"] = "Oddly Familiar Training Weapon", ["text"] = "Quest Item\n\"You're pretty sure you discarded this ages ago when trying to make more room in your bags. It was a trusty old friend.\"" }
entries[203388] = { ["name"] = "Gunky Insignia", ["text"] = "Quest Item\n\"The symbol has almost completely faded, but maybe the Kirin Tor will find it historically significant.\"" }
entries[203389] = { ["name"] = "Shiny Rock", ["text"] = "Quest Item\n\"It's shiny, so it must be important, right?!\"" }
entries[203390] = { ["name"] = "Maldra's Ring of Elemental Binding", ["text"] = "Quest Item\nUse: Bind Instigator Belaphon with Maldra's elemental magic. Only usable on enemies below 50% health.\n\"Maldra has infused this ring with the elemental binding spell that was used against her in the Misty Vale.\"" }
entries[203391] = { ["name"] = "Dented Dwarven Pocketwatch", ["text"] = "Quest Item\n\"An engraving on the back bears the name \"Professor Lichenrock\".\"" }
entries[203392] = { ["name"] = "Old Mirror Shard", ["text"] = "Quest Item\n\"It's still you, despite everything.\"" }
entries[203393] = { ["name"] = "Spongy Loamshroom", ["text"] = "Quest Item\n\"The pores on this mushroom make it ideal for soaking up toxins, for good or for ill.\"" }
entries[203394] = { ["name"] = "Elementally Charged Orb", ["text"] = "Quest Item\n\"A curious orb-shaped artifact that appears to be of titanic origin. However, a glow of elemental power emanates from within.\"" }
entries[203395] = { ["name"] = "Research Journal", ["text"] = "Quest Item\n\"The journal is in remarkable condition given its age. The notes within will no doubt keep Dragonscale scholars busy for years to come.\"\n<Right Click to Read>" }
entries[203396] = { ["name"] = "Displayed Armor Piece", ["text"] = "Quest Item\n\"This appears to be of black dragon design, but is much smaller than expected. Could it be an early example of dracthyr armor?\"" }
entries[203397] = { ["name"] = "Kirygosa's Note", ["text"] = "Binds when picked up\n\"A note in long, thin cursive and blue ink.\"\n<Right Click to Read>\nSell Price:" }
entries[203398] = { ["name"] = "Dampening Powder", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. Only a skilled alchemist could figure out how to use this ingredient for something useful.\"\nSell Price:" }
entries[203399] = { ["name"] = "Damaged Trident", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. Only a skilled blacksmith could restore this trident.\"\nSell Price:" }
entries[203400] = { ["name"] = "Lackluster Spices", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled chef might be able to save these flavors.\"\nSell Price:" }
entries[203401] = { ["name"] = "Dull Crystal", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled enchanter might find a use for this gem.\"\nSell Price:" }
entries[203402] = { ["name"] = "Broken Gnomish Voicebox", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled engineer might be able to repair this.\"\nSell Price:" }
entries[203403] = { ["name"] = "Hastily Scrawled Rune", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled scribe could clean up the linework and make this rune functional.\"\nSell Price:" }
entries[203404] = { ["name"] = "Crystal Fork", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled jewelcrafter could make this tuning fork sing.\"\nSell Price:" }
entries[203405] = { ["name"] = "Pristine Pelt", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled leatherworker might be able to turn this into something useful.\"\nSell Price:" }
entries[203406] = { ["name"] = "Torn Morqut Kite", ["text"] = "Artisan Curios\nBinds when picked up\nCrafting Reagent\n\"Dropped from creatures in the Forbidden Reach. A skilled tailor could mend this kite.\"\nSell Price:" }
entries[203407] = { ["name"] = "Draconic Suppression Powder", ["text"] = "Artisan Curios\n\"This solution is capable of countering certain efforts of Primalists in the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203408] = { ["name"] = "Ancient Ceremonial Trident", ["text"] = "Artisan Curios\n\"This trident isn't made of materials fit for combat--it seems ritualistic. Be careful where you place it in the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203409] = { ["name"] = "Sparkling Spice Pouch", ["text"] = "Artisan Curios\n\"The missing ingredient was love! The aroma is sensational. This is a wonderful taste from the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203410] = { ["name"] = "Glowing Crystal Bookmark", ["text"] = "Artisan Curios\n\"This glimmering bookmark is begging to be placed in a good book, like those found in the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203411] = { ["name"] = "Gnomish Voicebox", ["text"] = "Artisan Curios\n\"How did gnome tech even get to the Forbidden Reach? You'll need a buzzspire to play this on. May trigger a special encounter.\"\nSell Price:" }
entries[203412] = { ["name"] = "Arcane Dispelling Rune", ["text"] = "Artisan Curios\n\"After cleaning up the lines, you see this is a rune meant to dispel wards, like those used in the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203414] = { ["name"] = "Reinforced Pristine Leather", ["text"] = "Artisan Curios\n\"These strengthened leather patches are often used by Morqut Tuskarr to fix up some damaged hides in the Forbidden Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203415] = { ["name"] = "Traditional Morqut Kite", ["text"] = "Artisan Curios\n\"Some say the tuskarr kites tied to posts in the Forbidden Reach fly on the wings of spirits. May trigger a special encounter.\"\nSell Price:" }
entries[203416] = { ["name"] = "Dormant Lifebloom Seeds", ["text"] = "Artisan Curios\n\"Gathered in the Forbidden Reach. Local insects are attracted to aroma of this special flower's bloom. May trigger a special encounter.\"\nSell Price:" }
entries[203417] = { ["name"] = "Razor-Sharp Animal Bone", ["text"] = "Artisan Curios\n\"Skinned from creatures in the Forbidden Reach. This bone should be useful for cutting rough pelts from beasts in the Reach. May trigger a special encounter.\"\nSell Price:" }
entries[203418] = { ["name"] = "Amplified Quaking Stone", ["text"] = "Artisan Curios\n\"Gathered in the Forbidden Reach. This volatile stone could be used to push a rumbling mineral deposit in the Reach to its limit. May trigger a special encounter.\"\nSell Price:" }
entries[203419] = { ["name"] = "Elusive Croaking Crab", ["text"] = "Artisan Curios\n\"Caught in the Forbidden Reach. This noisy critter would make a good lure if you could find a local trap to put it in. May trigger a special encounter.\"\nSell Price:" }
entries[203420] = { ["name"] = "Recipe: Draconic Suppression Powder", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Forbidden Reach artisan curio.\nRequires Dragon Isles Alchemy (50)\nSell Price:" }
entries[203421] = { ["name"] = "Plans: Ancient Ceremonial Trident", ["text"] = "Binds when picked up\nUse: Teaches you how to repair a Forbidden Reach artisan curio.\nRequires Dragon Isles Blacksmithing (50)\nSell Price:" }
entries[203422] = { ["name"] = "Recipe: Sparkling Spice Pouch", ["text"] = "Binds when picked up\nUse: Teaches you how to repair a Forbidden Reach artisan curio.\nRequires Dragon Isles Cooking (50)\nSell Price:" }
entries[203423] = { ["name"] = "Formula: Glowing Crystal Bookmark", ["text"] = "Binds when picked up\nUse: Teaches you how to repair a Forbidden Reach artisan curio.\nRequires Dragon Isles Enchanting (50)\nSell Price:" }
entries[203424] = { ["name"] = "Schematic: Gnomish Voicebox", ["text"] = "Binds when picked up\nUse: Teaches you how to repair a Forbidden Reach artisan curio.\nRequires Dragon Isles Engineering (50)\nSell Price:" }
