entries[203427] = { ["name"] = "Pattern: Reinforced Pristine Leather", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Forbidden Reach artisan curio.\nRequires Dragon Isles Leatherworking (50)\nSell Price:" }
entries[203428] = { ["name"] = "Pattern: Traditional Morqut Kite", ["text"] = "Binds when picked up\nUse: Teaches you how to repair a Forbidden Reach artisan curio.\nRequires Dragon Isles Tailoring (50)\nSell Price:" }
entries[203430] = { ["name"] = "Ward of Igira", ["text"] = "Binds when picked up\n\"This series of customized fire protection tools will grant the wielder protection to interact with a Suffusion Crucible. The wards are consumed upon use.\"" }
entries[203431] = { ["name"] = "Ensemble: Burden of Unrelenting Justice", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Burden of Unrelenting Justice." }
entries[203432] = { ["name"] = "Bag of Spicy Pet Snacks", ["text"] = "Quest Item\nUnique\n\"Only a pet with a very strong constitution could enjoy one of these biscuits.\"" }
entries[203433] = { ["name"] = "Wheel of Whelpwhisper Brie", ["text"] = "Quest Item\nUnique\n\"A light buttery cheese with hints of nuttiness.\"" }
entries[203434] = { ["name"] = "Bottomless Bag of Blacksmithing Goods", ["text"] = "Binds when picked up\n\"Contains nearly everything to craft anything, assuming you're a Blacksmith.\"\n<Right Click to Open>" }
entries[203435] = { ["name"] = "Bottomless Bag of Alchemy Goods", ["text"] = "Binds when picked up\n\"Contains nearly everything to craft anything, assuming you're an Alchemist.\"\n<Right Click to Open>" }
