entries[203442] = { ["name"] = "Snail Slime", ["text"] = "Quest Item\n\"Potent slime from an incense snail. This is used as the base ingredient for niffen incense.\"" }
entries[203443] = { ["name"] = "Box of Leapmaize Crackers", ["text"] = "Quest Item\nUnique\n\"A box of crackers from The Roasted Ram.\"" }
entries[203444] = { ["name"] = "Bottomless Bag of Dragon Isles General Goods", ["text"] = "Binds when picked up\n\"Contains many common reagents shared between all professions. Still missing something? Check a nearby vendor!\"\n<Right Click to Open>" }
entries[203445] = { ["name"] = "Stuffed Doll", ["text"] = "Quest Item\nUnique\n\"A stuffed doll for any pet to enjoy.\"" }
entries[203446] = { ["name"] = "Soothing Incense", ["text"] = "Quest Item\nUnique\n\"A range of comforting smells for the home.\"" }
entries[203447] = { ["name"] = "Bottomless Bag of Optional Goods", ["text"] = "Binds when picked up\n\"Contains all of the stuff you could choose to ignore, but decided not to.\"\n<Right Click to Open>" }
entries[203448] = { ["name"] = "Bottomless Bag of Ore", ["text"] = "Binds when picked up\n\"Contains plenty of ore, and nothing more.\"\n<Right Click to Open>" }
entries[203449] = { ["name"] = "Bottomless Bag of Herbs", ["text"] = "Binds when picked up\n\"Contains a shower of flowers.\"\n<Right Click to Open>" }
entries[203450] = { ["name"] = "Bottomless Bag of Skins", ["text"] = "Binds when picked up\n\"Contains lots of skins, to help ensure your inevitable wins!\"\n<Right Click to Open>" }
entries[203451] = { ["name"] = "Decorative Shrubbery", ["text"] = "Quest Item\nUnique\n\"A nicely-shaped shrub with a certain pizzazz.\"" }
entries[203452] = { ["name"] = "Brewing Supplies?", ["text"] = "Quest Item\n\"Tough and fibrous, with a smell that might be best described as... fishy licorice?\"" }
entries[203453] = { ["name"] = "Dragonbone Totem", ["text"] = "Quest Item\n\"Djaradin runes are carved into the bone.\"" }
entries[203454] = { ["name"] = "Zaqali Equipment", ["text"] = "Quest Item\n\"The accoutrements of ritualistic dragonkillers, meant for ceremony as much as for warfare.\"" }
entries[203455] = { ["name"] = "Draketooth Fetish", ["text"] = "Quest Item\n\"A full set of young dragon teeth strung on a leather cord.\"" }
entries[203456] = { ["name"] = "Obsidian Prayer Beads", ["text"] = "Quest Item\n\"A string of dark beads that leave the smell of smoke on your hands.\"" }
entries[203457] = { ["name"] = "Volcanic Herb Sachet", ["text"] = "Quest Item\n\"The crushed herbs emit a faint crackling sound.\"" }
entries[203458] = { ["name"] = "Black Dragonscale Robes", ["text"] = "Quest Item\n\"Thick vestments made from stitched layers of black dragonhide.\"" }
entries[203459] = { ["name"] = "Totemic Ruins", ["text"] = "Quest Item\n\"Hacked pieces of petrified wood, iron, and fur.\"" }
entries[203460] = { ["name"] = "Onyx Annulet", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+693 Stamina\n\nPrimordial Socket\nPrimordial Socket\nPrimordial Socket\n\"Forged of elementium, this enigmatic ring has three vacant slots.\"\nSell Price:" }
entries[203461] = { ["name"] = "Chronologically Reallocated Rations", ["text"] = "Binds when picked up\nUse: Restore 10% health.\n\"Sold at pre-inflation prices.\"\nSell Price:" }
entries[203463] = { ["name"] = "Atrenosh's Journal", ["text"] = "Quest Item\n\"This rugged leatherbound tome contains rants about a soldier's life, violent descriptions of combat, and aspirational writing about weapons.\"" }
entries[203465] = { ["name"] = "Draconic Artifact", ["text"] = "Quest Item\n\"A carefully packaged artifact related to the legacy of the dracthyr. Can be traded to an envoy of the Dragonscale Expedition in the Forbidden Reach.\"" }
entries[203466] = { ["name"] = "Dragonscale Surplus Crate", ["text"] = "Quest Item\n\"Contains Dragon Isles Supplies and other rewards for assisting the Dragonscale Expedition in the Forbidden Reach.\"" }
entries[203469] = { ["name"] = "Coalesced Storm Remnants", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest" }
entries[203470] = { ["name"] = "Shikaar Banners", ["text"] = "Quest Item\nUse: Plant a Shikaar Banner onto all nearby Nokhud corpses. (2 Sec Cooldown)" }
entries[203471] = { ["name"] = "Tasty Candy", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Alchemy Knowledge by 3.\nRequires Dragon Isles Alchemy (25)\n\"Yum yum yum.\"" }
entries[203473] = { ["name"] = "Geyser Flower", ["text"] = "Quest Item\n\"This solitary flower seems to only grow at the base of the Ohn'iri Springs.\"" }
entries[203474] = { ["name"] = "Strong Salamanther Heart", ["text"] = "Quest Item\n\"This salamanther did not skip leg day.\"" }
entries[203475] = { ["name"] = "Urgent Stormwind Summons", ["text"] = "Quest Item\nUnique\n\"Rather inconspicuous, with a plain, unmarked wax seal.\"\n<Right Click to Read>" }
entries[203476] = { ["name"] = "Primalist Cache", ["text"] = "Binds when picked up\n\"Contains gold, Dragon Isles Supplies, and a chance for cosmetic Primalist weapons and armor.\"\n<Right Click to Open>" }
entries[203478] = { ["name"] = "Field Deployable Heat Source", ["text"] = "Binds when picked up\nUse: Builds a fire that provides a source of Warmth to nearby allies for 15 sec.\n\nOnly usable within the Primalist Future during the Storm's Fury event.\nSell Price:" }
entries[203489] = { ["name"] = "Virtuous Silver Breastplate", ["text"] = "Binds when picked up\nChest Plate\n1273 Armor\n+391 [Strength or Intellect]\n+1,044 Stamina\n+ 477 Haste\n+ 191 Mastery\nDurability 165 / 165\nClasses: Paladin\nVirtuous Silver Cataphract (0/5)\nVirtuous Silver Breastplate\nVirtuous Silver Gauntlets\nVirtuous Silver Heaume\nVirtuous Silver Cuisses\nVirtuous Silver Pauldrons\n(2) Set Holy: Holy Shock increases the chance for your spells to critically strike by 4% for 10 sec.\n(2) Set Protection: Avenger's Shield grants you and your closest ally Ally of the Light, increasing Versatility by 8% for 8 sec. (1s cooldown)\n(2) Set Retribution: Judgment, Blade of Justice, and Wake of Ashes damage increased by 15%.\n(4) Set Holy: Holy Light, Flash of Light, Light of Dawn, Word of Glory, and Bestow Faith healing is increased by 6% and their critical effects increase the damage or healing of your next Holy Shock by 20%.\n(4) Set Protection: [ Hammer of the Righteous ] [ Blessed Hammer / Crusader Strike ] increases your Parry by 7% for 10 sec, and extends the duration of Ally of the Light by 1.0 sec.\n(4) Set Retribution: Your damaging Holy Power abilities deal 10% increased damage.\nSell Price:" }
