entries[203681] = { ["name"] = "Stormed Primalist Cache", ["text"] = "Binds when picked up\n\"Contains a Storm Sigil, Dragon Isles Supplies, Primalist treasures, and a chance for cosmetic Primalist weapons and armor.\"\n<Right Click to Open>" }
entries[203682] = { ["name"] = "Darkened Elemental Core", ["text"] = "Quest Item\n\"Hissed voices tickle the back of your mind, half-words and hushed secrets.\"" }
entries[203683] = { ["name"] = "Ward of Fyrakk", ["text"] = "Binds when picked up\n\"This series of customized fire protection tools will grant the wielder protection to interact with a Suffusion Mold. The wards are consumed upon use.\"" }
