entries[203686] = { ["name"] = "Odd Round Object", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"This is slightly squishy to the touch, and has three claw holes of roughly drake size. Maybe it's of interest to Voraxian.\"" }
entries[203687] = { ["name"] = "Dusty Vase", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A dusty vase, it depicts a dragon fighting what looks like a djaradin, along with some text you can barely make out. Maybe it's of interest to Voraxian.\"" }
