entries[203704] = { ["name"] = "Stone Dissolver", ["text"] = "Binds when picked up\nUnique (20)\nDuration: 2 hrs (real time)\nUse: Toss on annoying stone blockages to completely dissolve them. (10 Sec Cooldown)\n\"For internal or external use.\"\nSell Price:" }
