entries[203707] = { ["name"] = "Water Bucket", ["text"] = "Quest Item\nUnique\nUse: Throw a bucket of water, extinguishing all fires within 3 yards of the targeted area.\n\"A bucket of fresh cave water used by niffen potters.\"" }
entries[203708] = { ["name"] = "Conch Whistle", ["text"] = "Binds when picked up\nUnique\nUse: Summon and dismiss Big Slick in the City.\n\"Use this whistle to call Big Slick while you're training him with Briggul in Glimmerogg.\"" }
entries[203710] = { ["name"] = "Everburning Key", ["text"] = "Binds when picked up\nUnique (3)\n\"One of several keys required to open a Secured Shipment. Trusted only to Igira's finest blacksmiths, these keys are consumed upon their use.\"" }
entries[203712] = { ["name"] = "Soft Peafowl Down", ["text"] = "Quest Item\n\"The perfect material for stuffing pillows.\"" }
entries[203713] = { ["name"] = "Mysterious Flower", ["text"] = "Binds when picked up\n\"A beautiful cut flower. A small written note is attached to the stem: \"The legends are true.\" You don't remember picking this up.\"\nSell Price:" }
entries[203714] = { ["name"] = "Ward of Faceless Ire", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+487 [Agility or Strength or Intellect]\nUse: Grant an ally Writhing Ward for 10 sec, absorbing up to 177207 damage. If broken, the Ward coalesces into Writhing Ire, dealing [source value] Shadowflame damage over 6 sec to the last enemy to strike it. (1 Min Cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[203715] = { ["name"] = "Oozing Gold", ["text"] = "Binds when picked up\nUnique (20)\nDuration: 2 hrs (real time)\nUse: Toss to release the slimy golden liquid within. (10 Sec Cooldown)\n\"Pretty to look at, difficult to spend.\"\nSell Price:" }
entries[203716] = { ["name"] = "Thundering Banner of the Aspects", ["text"] = "Binds when picked up\nToy\nUse: Plant a banner representing your successes against the Thundering. (10 Min Cooldown)" }
entries[203718] = { ["name"] = "Vial of Flames", ["text"] = "Binds when picked up\nUnique (20)\nDuration: 2 hrs (real time)\nUse: Toss to engulf an area in magical flames. (10 Sec Cooldown)\n\"Handle with care.\"\nSell Price:" }
entries[203720] = { ["name"] = "Restorative Water", ["text"] = "Binds when picked up\nUnique (20)\nDuration: 2 hrs (real time)\nUse: Toss to release the restorative water within. (10 Sec Cooldown)\n\"Magically purified and imbued for millennia.\"\nSell Price:" }
entries[203722] = { ["name"] = "Experimental Dragon Pack", ["text"] = "Binds when picked up\nUnique (20)\nUse: Activate the Dragon Pack to propel you forward in the air. Usable in Zskera Vaults and the Forbidden Reach. (30 Sec Cooldown)" }
entries[203724] = { ["name"] = "Field Medic's Hazard Payout", ["text"] = "Binds when picked up\n\"A stockpile of miscellaneous goods that compensates for the underappreciated work out in the battlefield.\"\n<Right Click to Open>" }
entries[203725] = { ["name"] = "Display of Strength", ["text"] = "Binds when picked up\nToy\nUse: Caber Toss! (2 Min Cooldown)\n\"Show'em what you've got!\"" }
entries[203727] = { ["name"] = "Gleaming Moonbeast's Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Armored in glistening silver, these devoted mounts are said to be a blessing from Elune herself.\"\nPromotion" }
entries[203729] = { ["name"] = "Ominous Chromatic Essence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+460 [Agility or Strength or Intellect]\nEquip: Resonate with the power of your sworn dragonflight, granting you 475 secondary stat. Allies sworn to a different dragonflight gain 50 secondary stat from your Resonance. You may only benefit from one Resonance per Flight.\nUse: Attune with a nearby dragonflight Oathstone in the Dragon Isles.\n\"The beauty of its swirling colors belies the cruel experiments that followed.\"\nSell Price:" }
