entries[203731] = { ["name"] = "Enchanted Bandage", ["text"] = "Quest Item\nUse: Heal current wounded ally.\n\"Magically enhanced for use by those who have not learned the art of healing.\"" }
entries[203734] = { ["name"] = "Snow Blanket", ["text"] = "Binds when picked up\nToy\nUse: Get buried in snow! (10 Min Cooldown)\nRequires Revered reputation with the Winterpelt Furbolg on at least one character in your Warband.\nSell Price:" }
