entries[204091] = { ["name"] = "Rocket Shredder 9001", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The salesgoblin always tells people about the RS-9001's huge variety of attachments, but somehow neglects to mention that you never get to pick the attachments it'll have when you mount up.\"\nRecruit-a-Friend" }
