entries[204177] = { ["name"] = "Nasz'uro, the Unbound Legacy", ["text"] = "Binds when picked up\nUnique\nOne-Hand Fist Weapon\n633 - 902 Damage Speed 2.60\n(295.2 damage per second)\n+3,026 Intellect\n+2,378 Stamina\n+ 230 Versatility\n+ 326 Mastery\nDurability 95 / 95\nClasses: Evoker\nEquip: Your Empower spells activate the Order magic within, releasing a sphere of Order that seeks a powerful ally, increasing their primary stat by 746 and Speed by 732 for 10 sec.\nSell Price:" }
entries[204178] = { ["name"] = "Snailcatcher Net", ["text"] = "Quest Item\nUse: Throw a net to catch an Aimless Snail.\n\"Specially designed to snare even the slipperiest snails.\"" }
