entries[204181] = { ["name"] = "Opera of the Aspects", ["text"] = "Binds when picked up\n\"Most of the pages are blank, but there is what appears to be the end of a play written in the back, as if someone wanted to write the ending first.\"\n<Right Click to Read>\nSell Price:" }
entries[204182] = { ["name"] = "Cloak of Dark Descent", ["text"] = "Cosmetic\nBinds to Warband\nBack\nUse: Add this appearance to your Warband collection." }
