entries[204184] = { ["name"] = "Ebon Eviscerator", ["text"] = "Quest Item\n\"Ancient, but just as deadly as the day it was forged.\"" }
entries[204185] = { ["name"] = "The Old Gods and the Ordering of Azeroth (Annotated)", ["text"] = "Binds when picked up\nUnique\n\"An ancient copy, transcribed by an unknown hand for Neltharion's private collection. Notes have been scribbled in the margins.\"\n<Right Click to Read>\nSell Price:" }
entries[204186] = { ["name"] = "Greater Obsidian Trophy of Conquest", ["text"] = "Binds when picked up\nOptional Crafting Reagent\n\nProvides the following property: Increases item level to 450 in Arenas and Battlegrounds.\nUsable with: Craftable epic items in the Head, Chest, or Leg slots crafted with a Spark of Shadowflame.\n\"A testament to your monumental victories on the battlefield.\"\nSell Price:" }
