entries[204201] = { ["name"] = "Neltharion's Call to Chaos", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 586 Critical Strike\nClasses: Warrior , Paladin , Mage , Demon Hunter , Evoker\nEquip: Your area effect spells and abilities have a chance to grant you 1974 Primary Stat and increase damage you receive by 5% for 18 sec.\nSell Price:" }
