entries[204322] = { ["name"] = "Failure Disposal Cannon", ["text"] = "Binds when picked up\nRanged Gun\n786 - 1,461 Damage Speed 3.00\n(374.5 damage per second)\n+498 Agility\n+1,586 Stamina\n+ 373 Versatility\n+ 406 Mastery\nDurability 120 / 120\nSell Price:" }
entries[204323] = { ["name"] = "Old Trunk Key", ["text"] = "Binds when picked up\n\"An old and slightly rusty key. Its shaft is pocked with chew marks.\"" }
entries[204324] = { ["name"] = "Echo's Maddening Volume", ["text"] = "Binds when picked up\nHeld In Off-hand\n+785 Intellect\n+828 Stamina\n+ 266 Haste\n+ 129 Mastery\nSell Price:" }
entries[204325] = { ["name"] = "Crude Key Fragment", ["text"] = "Binds when picked up\nUnique (5)\nUse: Combine five Crude Key Fragments.\n\"A piece of a broken key.\"" }
entries[204326] = { ["name"] = "Strange Artifact", ["text"] = "Quest Item" }
entries[204327] = { ["name"] = "Titan Machine Part", ["text"] = "Binds when picked up\nDuration: 10 min (real time)" }
entries[204328] = { ["name"] = "Return of the Nightsquall", ["text"] = "Binds when picked up\nUnique\n\"Stained by saltwater and smelling of rum and... bananas?\"\n<Right Click to Read>\nSell Price:" }
entries[204329] = { ["name"] = "Petrified Spider Leg", ["text"] = "Quest Item\n\"Ew. Ew, ew, ew, ew, ew, ew, ew, ew.\"" }
entries[204330] = { ["name"] = "Inert Primordial Fragments", ["text"] = "Binds when picked up\n\"The digestive juices of the slime has drained this gem of any power.\"\nSell Price:" }
entries[204331] = { ["name"] = "Djaradin Pillar Shard", ["text"] = "Binds when picked up\nDuration: 10 min (real time)" }
entries[204334] = { ["name"] = "Waste Disposal Notes", ["text"] = "Quest Item\n\"This timeworn ledger contains grisly notes on numbered experiment subjects and their ultimate end.\"\n<Right Click to Read>" }
entries[204335] = { ["name"] = "A Song of the Depths", ["text"] = "Binds when picked up\nUnique\n\"A chilling missive written from the deep.\"\n<Right Click to Read>\nSell Price:" }
entries[204336] = { ["name"] = "Awakened Heirloom Armor Casing", ["text"] = "Binds to Warband\nUse: Upgrade an heirloom armor, trinket, shield or off-hand allowing it to increase in power up to level 70.\n\nOnly works on heirlooms that scale to level 60." }
entries[204337] = { ["name"] = "Awakened Heirloom Scabbard", ["text"] = "Binds to Warband\nUse: Upgrade an heirloom weapon allowing it to increase in power up to level 70.\n\nOnly works on heirlooms that scale to level 60." }
entries[204338] = { ["name"] = "The Burden of Lapisagos", ["text"] = "Binds when picked up\nUnique\n\"A book scribed with shifting arcane runes holding ancient magic.\"\n<Right Click to Read>\nSell Price:" }
entries[204339] = { ["name"] = "Satchel of Coalescing Chaos", ["text"] = "Binds to Warband\nUse: Open to gain 60 Primal Chaos.\n\"A satchel sold by Rabul of the Artisan's Consortium. It rumbles in agitation and expands with limitless possibility.\"" }
entries[204340] = { ["name"] = "Torn Recipe Scrap", ["text"] = "Binds when picked up\nUse: Piece together 30 Torn Recipe Scraps to discover the rat's secret recipe." }
entries[204342] = { ["name"] = "Questionable Jerky", ["text"] = "Binds when picked up\nUse: Eat the Questionable Jerky.\n\"The smell alone is enough to tell you that eating this would likely be a bad idea.\"" }
entries[204343] = { ["name"] = "Trusty Dragonkin Rake", ["text"] = "Quest Item\nUse: Throw a rake at a Ripened Dragonfruit to knock it to the ground. (3 Sec Cooldown)\nRequires level 10 to 70 ( 70)\n\"Sturdy, well-worn, and surprisingly aerodynamic.\"" }
entries[204344] = { ["name"] = "Conductive Lodestone", ["text"] = "Quest Item\nUse: Siphons power from nearby slain Crumbling Scoria.\n\nOnce the lodestone has been fully charged, use it on High Summoner Wahuna to overload her shield.\n\"The polished stone tugs you towards sources of great elemental power.\"" }
entries[204345] = { ["name"] = "Note to Disposal Site", ["text"] = "Binds when picked up\n\"This note contains orders sent to the Gaze of Neltharion.\"\n<Right Click to Read>" }
entries[204346] = { ["name"] = "Arclight Rumble Foil Box", ["text"] = "Binds to Warband\n\"What could be inside?\"\n<Right Click to Open>" }
entries[204347] = { ["name"] = "Pool Contaminant", ["text"] = "Binds when picked up\nDuration: 10 min (real time)" }
entries[204348] = { ["name"] = "Balled-up Rumble Foil", ["text"] = "Binds to Warband\nUse: Flatten this out.\n\"Flatten this out.\"" }
entries[204349] = { ["name"] = "Bigger Wrench", ["text"] = "Binds when picked up\nUnique\nDuration: 10 min (real time)" }
entries[204351] = { ["name"] = "Animated Crystal Shard", ["text"] = "Binds when picked up\nUnique\nDuration: 10 min (real time)\nThis Item Begins a Quest" }
entries[204352] = { ["name"] = "Leftover Elemental Slime", ["text"] = "Binds when picked up\nUse: Combine 50 Leftover Elemental Slimes to create something new.\n\"Squirming elemental slime gathered off of powerful primalist leaders. This mass seems to want to pull itself back together.\"" }
entries[204353] = { ["name"] = "Primordial Jeweler's Kit", ["text"] = "Quest Item\n\"A collection of unique tools. Mastery of them would take years to learn.\"" }
entries[204354] = { ["name"] = "Hollowed Furbolg Food Pack", ["text"] = "Cosmetic\nBinds to Warband\nBack\nRequires Honored reputation with the Winterpelt Furbolg on at least one character in your Warband.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[204355] = { ["name"] = "Hollowed Winterpelt Food Pack", ["text"] = "Cosmetic\nBinds to Warband\nBack\nRequires Revered reputation with the Winterpelt Furbolg on at least one character in your Warband.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[204356] = { ["name"] = "Illustrious Gemdust", ["text"] = "Binds when picked up\nCrafting Reagent\n\"Acquired by Jewelcrafters by crushing gems revealed by the Cataclysm. Can be exchanged in Stormwind or Orgrimmar for Illustrious Jewelcrafter's Tokens.\"\nSell Price:" }
entries[204359] = { ["name"] = "Reach Racer's Purse", ["text"] = "Binds when picked up\n\"Filled with gold, Dragon Isles Supplies, and a chance for a Drakewatcher's Manuscript.\"\n<Right Click to Open>" }
entries[204360] = { ["name"] = "Strange Petrified Orb", ["text"] = "Binds when picked up\nUse: Combine the Strange Petrified Orb and a Scrap of Black Dragonscales to reverse the petrification.\n\"Trapped in the vaults for thousands of years, this object is completely rock hard. Perhaps a powerful source of earth magic could restore it.\"" }
entries[204361] = { ["name"] = "Winding Slitherdrake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These drakes feel at home in the depths of the earth and the far reaches of the sky.\"\nAchievement:\nA Serpentine Discovery" }
entries[204363] = { ["name"] = "Particularly Ordinary Egg", ["text"] = "Binds when picked up\nUse: Combine your Particularly Ordinary Egg and a Drop of Blue Dragon Magic to enchant it.\n\"There seems to be nothing unique about this egg at all. Maybe it can be empowered by something found within the vaults.\"" }
entries[204364] = { ["name"] = "Magically Altered Egg", ["text"] = "Binds when picked up\nUse: Combine your Magically Altered Egg and some Everburning Ruby Coals to hatch it.\n\"An egg that has been enhanced with mysterious blue dragon magic. If only you could find something in the vaults that could hatch it.\"" }
entries[204365] = { ["name"] = "Bundle of Ebon Spears", ["text"] = "Quest Item\nUse: Drive an Ebon Spear into the corpse of a Zaqali djaradin. (5 Sec Cooldown)\n\"A collection of spears wielded by the black dragonflight, still as sharp as the day they were forged.\"" }
entries[204366] = { ["name"] = "Egg of Unknown Contents", ["text"] = "Binds when picked up\nUse: Combine your Egg of Unknown Contents and a Speck of Bronze Dust to age your egg.\n\"The mysterious egg has finally hatched, but you can't make out what creature is inside. Maybe it will look better when it's grown up. Something in the vaults should speed it along.\"" }
entries[204367] = { ["name"] = "Sleeping Ancient Mammoth", ["text"] = "Binds when picked up\nUse: Combine your Sleeping Ancient Mammoth and an Emerald Dragon Brooch to waken it.\n\"Your altered egg grew into a mammoth? That doesn't seem right, but there's no use stopping now. Find a way to wake it up and claim your prize!\"" }
entries[204369] = { ["name"] = "Scrap of Black Dragonscales", ["text"] = "Binds when picked up\nUse: Combine the Strange Petrified Orb and a Scrap of Black Dragonscales to reverse the petrification.\n\"A glimmer of earth magic still resides within these molted black dragon scales. It might be able to reverse minor petrifications.\"" }
entries[204370] = { ["name"] = "Stinky Bright Potion", ["text"] = "Toxic\nUse: Brightens the world around you.\n\"Mix two parts crushed saxifrage, one part pure decay, and throw in some mysterious spores to keep the imbiber on their toes.\"\nSell Price:" }
entries[204371] = { ["name"] = "Drop of Blue Dragon Magic", ["text"] = "Binds when picked up\nUse: Combine your Particularly Ordinary Egg and a Drop of Blue Dragon Magic to enchant it.\n\"The picture on the vial is hard to make out, but you're sure it's a dragon. They should consider relabeling these.\"" }
entries[204372] = { ["name"] = "Speck of Bronze Dust", ["text"] = "Binds when picked up\nUse: Combine your Egg of Unknown Contents and a Speck of Bronze Dust to age your egg.\n\"Nobody would hide dust in a treasure vault. This is likely a potent bronze dragon catalyst for time magic. Be careful not to use too much!\"" }
entries[204373] = { ["name"] = "Banged-up Rumble Foil", ["text"] = "Binds to Warband\nUse: Flatten this out.\n\"Flatten this out.\"" }
entries[204374] = { ["name"] = "Emerald Dragon Brooch", ["text"] = "Binds when picked up\nUse: Combine your Sleeping Ancient Mammoth and an Emerald Dragon Brooch to waken it.\n\"Though cracked, you can feel the power of the Emerald Dream hidden within. This should wake any creature.\"" }
entries[204375] = { ["name"] = "Everburning Ruby Coals", ["text"] = "Binds when picked up\nUse: Combine your Magically Altered Egg and some Everburning Ruby Coals to hatch it.\n\"A handful of coals that are warm to the touch. This must be from the healing fires of an ancient Red Dragon. Maybe this can help grant life in something small.\"" }
entries[204377] = { ["name"] = "Glow Spores", ["text"] = "Quest Item\n\"Glowing fungus that sniffing mice have a particular aptness to track down.\"" }
entries[204378] = { ["name"] = "Brimming Dragonscale Expedition Supply Pack", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the Dragonscale Expedition.\"\n<Right Click to Open>" }
entries[204379] = { ["name"] = "Brimming Iskaaran Supply Pack", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the Iskaara Tuskarr.\"\n<Right Click to Open>" }
entries[204380] = { ["name"] = "Brimming Maruuk Centaur Supply Satchel", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the Maruuk Centaur.\"\n<Right Click to Open>" }
entries[204381] = { ["name"] = "Brimming Valdrakken Accord Supply Pack", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the Valdrakken Accord.\"\n<Right Click to Open>" }
entries[204382] = { ["name"] = "Noble Bruffalon", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It is a great honor to be trusted with one of the Maruuk's loyal hunting companions. This Bruffalon is reliable and steadfast through any hardship.\"\nVendor:\nStorykeeper Ashekh\nZone:\nThe Forbidden Reach\nCost:\n100000" }
entries[204383] = { ["name"] = "Sack of Oddities", ["text"] = "Binds when picked up\n\"The Dragonscale Expedition collect such a wide assortment of trinkets and baubles even they aren't certain what's inside.\"\n<Right Click to Open>" }
entries[204386] = { ["name"] = "Pocket Darkened Elemental Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+329 [Agility or Strength or Intellect]\nUse: Throw a small Darkened Elemental Core at the target location dealing 63430 Shadowflame damage split between all enemies. (1 Min, 30 Sec Cooldown)\n\"Even at this size, elemental cores can syphon enough of the surrounding Shadowflame energy to turn into a small but deadly explosive.\"\nSell Price:" }
entries[204387] = { ["name"] = "Buzzing Orb Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+320 [Agility or Strength or Intellect]\nEquip: Slowly build up stacks of titan energy. The amount of stacks gained per second can vary but when fully charged at 120 stacks the Buzzing Orb Core will increase a random secondary stat by 1075 , as well as your movement speed by 1075 for 20 sec.\n\"This titan artifact stores energy that can be used to power the carrier's abilities.\"\nSell Price:" }
entries[204388] = { ["name"] = "Draconic Cauterizing Magma", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+329 Intellect\nUse: Shield an ally for 53847 while channeling a beam of molten flame dealing [source value] Fire damage over 2.5 sec to them. If they survive the channel, heal them for 134618 . (2 Min Cooldown)\nSell Price:", ["unresolvedValues"] = true }
